class Solution {
    int gcd(int a, int b) {
        while (b) {
            int t = b;
            b = a % b;
            a = t;
        }
        return a;
    }
public:
    bool hasGroupsSizeX(vector<int>& deck) {
        unordered_map<int, int> count;
        for (int card : deck) {
            count[card]++;
        }
        int g = 0;
        for (auto& p : count) {
            g = gcd(g, p.second);
        }
        return g >= 2;
    }
};
